# -*- coding: utf-8 -*-
# Обновление системного промта kip8 до post-Task 309 (перенос из kip8test@5640d60)
with open('Системный_промт_для_приложения_КИПиА.md') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-04 (post-Task 309: ПЕРЕНОС Task 309 из kip8test@5640d60 в боевой kip8 одним инкрементом SW kipia-v413→v414 — заявка пользователя: «при наведении указателя мыши или при нажатии на поле с сотрудником (слева от шахматки), должно появляться окно с данными сотрудника, которые раньше были в убранных вкладках (сотрудники, отпуска, инструктажи). Так же сделай возможность редактирования и удаления добавляемых мероприятий в ячейки. Коды "д" и "н", добавляемые в шахматку пользователем вручную, должны отображаться с обрамлением по краям, по примеру как в их миниатюрах». СОДЕРЖАНИЕ: 1) КАРТОЧКА СОТРУДНИКА (#wsEmpPopup .ws-cell-popup.ws-emp-popup + #wsEmpPopupCloser) — попап у колонки ФИО при НАВЕДЕНИИ курсора (задержка 350 мс; делегированные mouseover/mouseout на #wsGridWrap по data-tab ячейки, слушатели один раз в init — _attachEmpPopupHover, переживают innerHTML-перерисовки; тач (hover: none) игнорируется) и по КЛИКУ (onEmpCellClick — прикреплённый режим: кловер active, закрытие кликом по фону или Esc). Три секции с данными убранных вкладок (Task 307/308): «Сотрудник» (тип/смена, должность, шаблон ротации — имя из _PATTERNS, старт цикла, дата приёма, комментарий), «Отпуска · год шахматки» (периоды по частям, фильтр _vacDaysInYear, «Итого в году»), «Мероприятия · месяц» (свотч кода + тема + период). Hover-режим: закрытие при уходе курсора через 400 мс, вход в попап (mouseenter) отменяет — кнопки ✎/✕ кликабельны; переход на ячейку дня закрытие НЕ отменяет. Взаимная блокировка со статусным попапом; Esc закрывает оба; колонка ФИО — cursor pointer + СПЛОШНАЯ hover-подсветка (sticky). 2) ПРАВКА/УДАЛЕНИЕ МЕРОПРИЯТИЙ (кнопки только _canEdit): ✎/✕ (stopPropagation) в секции «Мероприятия в этот день» попапа ячейки И в карточке сотрудника; editTraining(id) → шторка #wsTrSheet в режиме «Правка мероприятия» (#wsTrSheetTitle, кнопка «Сохранить» #wsTrSubmitBtn, префилл записи, _editTrainingId); submit в правке = addTraining(новые значения) → deleteTraining(старый id) — серверного updateTraining НЕТ, Apps Script НЕ менялся; порядок add→delete: сбой add не трогает старую запись, сбой delete после add — видимый дубль + тост ошибки; тост «Мероприятие обновлено» + loadGrid; deleteTraining — kipConfirm, попапы закрываются до диалога; авто-строки Записи_графика со старым FK снимет «Сформировать» (шаг 4.6), новые создаст с новым id (шаг 4) — регенерация сходится. 3) РУЧНЫЕ Д/Н: класс ws-manual-dn (источник «руч» И статус д/н; pending уже «руч» — рамка видна ДО сохранения) — box-shadow inset 2px по краям (тёмная rgba(255,255,255,.85) / светлая rgba(38,50,56,.75)) — как у миниатюры-свотча попапа статуса; плановые Д/Н и прочие ручные коды — прежний вид (ws-source-manual 1.5px). 4) РЕГРЕСС-ФИКСЫ TASK 308: вызовы удалённых со страницами loadTrainings()/loadVacations() (после добавления/удаления мероприятия тостил ложную «Ошибка: … is not a function» и не перезагружал сетку) заменены на loadGrid(). ПЕРЕНЕСЕНО: index.html — патч 780 строк (git apply, чисто); sw.js kipia-v413→v414; tests/ — test-task309.js копия (+19 тестов) с адаптацией версий (kipia-test-v548→v414), test-work-schedule.js/test-work-events.js копии с адаптацией (v548→v414, v546→v412, v539→v410 и исторические), 8 файлов бамп kipia-v413→v414, run-all.js +require; scripts/: НОВЫЕ task309-browser-check.py (порт 8928) + DEPLOY-Task309-emp-card-events.md + пруфы task309-proof-*.png. СЕРВЕР WorkSchedule.gs и листы НЕ менялись — Apps Script НЕ трогать (единственный инкремент SW). Тесты: 1457 → 1476 passed / 0 failed (ПАРИТЕТ с kip8test@5640d60). Верификация: scripts/task309-browser-check.py — 27/27 PASS на РЕАЛЬНОМ kip8/index.html (порт 8928: hover-карточка Иванова со всеми секциями; уход курсора закрывает, вход в карточку отменяет; клик — pinned; попап ячейки 10.09 с ✎/✕; ✎ → «Правка мероприятия» с префиллом; смена темы → add+delete на сервере, тост «Мероприятие обновлено», перезагрузка; ✕ → kipConfirm → deleteTraining; ручная «д» 12.09 — ws-manual-dn + inset 2px (авто «Н» — без); 375px — карточка в экране, без переполнения; «ИТР8 pro» — справка без кнопок; 0 JS-ошибок). АКТУАЛИЗАЦИЯ: ~39.9 тыс. строк, тесты 1476 (27 тест-файлов .js), пример CACHE_VERSION kipia-v414. ДЕПЛОЙ ПОЛЬЗОВАТЕЛЯ: ТОЛЬКО фронтенд — GitHub Pages подхватит сам (1–3 мин после push), затем Ctrl+Shift+R ×1–2 (SW v414); Apps Script и листы НЕ трогать (сервер не менялся с Task 306). kip8-desktop синхронизируется АВТОМАТИЧЕСКИ (sync-to-desktop.yml: index.html + sw.js + scripts/*.gs + tests). Последнее изменение КОДА: Task 309.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
prev = [i for i, l in enumerate(lines[:30]) if l.startswith('> **Версия документа (предыдущая):**')]
while len(prev) > 12:
    del lines[prev[-1]]
    prev = [i for i, l in enumerate(lines[:30]) if l.startswith('> **Версия документа (предыдущая):**')]
print('Строка 3 вставлена; цепочка «предыдущих»:', len(prev))

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-v413`', '> **Текущая версия кэша:** `kipia-v414`'),
    ('| `kip8` | PWA + APK | `kipia-v413` |', '| `kip8` | PWA + APK | `kipia-v414` |'),
    ('весь код в одном `index.html` (~39.3 тыс.', 'весь код в одном `index.html` (~39.9 тыс.'),
    ('| Тесты | Node.js + кастомный фреймворк (`tests/`, 1457 теста, `node tests/run-all.js`)', '| Тесты | Node.js + кастомный фреймворк (`tests/`, 1476 теста, `node tests/run-all.js`)'),
    ('# 1457 юнит-теста (Node.js, 26 файлов)', '# 1476 юнит-теста (Node.js, 27 файлов)'),
    ('`CACHE_VERSION` (например, `kipia-v413`)', '`CACHE_VERSION` (например, `kipia-v414`)'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Счётчики обновлены (%d замен)' % len(reps))

# строка 160: 26 файлов тестов
n = src.count('`tests/`, 1457 теста')
src = src.replace('# 1457 юнит-теста (Node.js, 26 файлов):', '# 1476 юнит-теста (Node.js, 27 файлов):')

old725 = '> **Последняя принятая партия:** Tasks 298-308 (коды статусов Т-12/Т-13, мероприятия И/ОБ/ПЗ/ПР/*, таб_№ текстом, отпуск + плановая смена бейджем, одна кнопка «Сформировать», удаление вкладки «Сотрудники» + кнопка «+ Сотрудник» в тулбаре, удаление вкладок «Инструктажи»/«Отпуска» + кнопка «+ Отпуск» в тулбаре) — Task 308 из kip8test@9698926, kipia-v413, паритет тестов 1457/0 (Task 308-перенос, 2026-09-04; Apps Script НЕ трогать — сервер не менялся с Task 306; листы не трогать).'
new725 = '> **Последняя принятая партия:** Tasks 298-309 (коды статусов Т-12/Т-13, мероприятия И/ОБ/ПЗ/ПР/*, таб_№ текстом, отпуск + плановая смена бейджем, одна кнопка «Сформировать», удаление вкладки «Сотрудники» + кнопка «+ Сотрудник» в тулбаре, удаление вкладок «Инструктажи»/«Отпуска» + кнопка «+ Отпуск» в тулбаре, карточка сотрудника у колонки ФИО + правка/удаление мероприятий + рамка ручных д/н) — Task 309 из kip8test@5640d60, kipia-v414, паритет тестов 1476/0 (Task 309-перенос, 2026-09-04; Apps Script НЕ трогать — сервер не менялся с Task 306; листы не трогать).'
assert old725 in src, 'строка партии 298-308 не найдена'
src = src.replace(old725, new725)
print('Строка 725 (последняя партия) обновлена')

# Новая запись в секции модуля (после записи переноса Task 307 —
# Task 308 записи-маркера не имеет, он в строке версии и в партии)
lines2 = src.split('\n')
insert_at = None
for i, l in enumerate(lines2):
    if l.startswith('- **Перенос Task 307:'):
        j = i + 1
        while j < len(lines2) and not lines2[j].startswith('---'):
            j += 1
        insert_at = j
        break
assert insert_at is not None, 'точка вставки (после записи Task 307) не найдена'
entry = ('- **Перенос Task 309: карточка сотрудника у колонки ФИО, правка/удаление мероприятий, рамка ручных д/н** (Task 309-перенос из kip8test@5640d60, один инкремент SW kipia-v413→v414, сервер/листы не менялись): 1) #wsEmpPopup (+ #wsEmpPopupCloser) — наведение (350 мс, делегирование на #wsGridWrap по data-tab, (hover: hover), закрытие через 400 мс с отменой по mouseenter попапа) или клик (pinned: кловер/Esc) открывают карточку с тремя секциями данных убранных вкладок: «Сотрудник» (тип/смена, должность, шаблон ротации из _PATTERNS, старт цикла, дата приёма, комментарий), «Отпуска · год сетки» (части/периоды/итог _vacDaysInYear), «Мероприятия · месяц» (свотч+код+тема+период); взаимная блокировка со статусным попапом; 2) кнопки ✎/✕ (только _canEdit) в «Мероприятиях в этот день» попапа ячейки и в карточке; правка — шторка #wsTrSheet «Правка мероприятия» (префилл, _editTrainingId), сохранение = addTraining+deleteTraining (updateTraining на сервере нет, Apps Script не трогаем), тост «Мероприятие обновлено» + loadGrid; удаление — kipConfirm; 3) ручные д/н — класс ws-manual-dn (рамка inset 2px по краям, тёмная/светлая темы); 4) регресс-фиксы Task 308: вызовы удалённых loadTrainings()/loadVacations() → loadGrid(). Верификация: патч index.html 780 строк чисто, тесты 1457→1476/0 (паритет), task309-browser-check 27/27 на реальном kip8/index.html (порт 8928), VLM ×4. ДЕПЛОЙ: только GitHub Pages + Ctrl+Shift+R ×1–2 (SW v414); Apps Script/листы не трогать; kip8-desktop — автосинк. См. scripts/DEPLOY-Task309-emp-card-events.md')
lines2.insert(insert_at, entry)
src = '\n'.join(lines2)
print('Запись Task 309 (после Task 307, строка %d)' % insert_at)

with open('Системный_промт_для_приложения_КИПиА.md', 'w') as f:
    f.write(src)
print('Промт kip8 записан:', len(src), 'символов')
